import { Container, FederatedPointerEvent, Graphics, Point, Sprite, Texture } from 'pixi.js';

import { eventEmitter } from '../../services/event-emitter';
import { AssetManager } from '@game-studio/asset-manager';
import { BaseChip } from './base-chip';
import gsap from 'gsap';

const VISIBLE_CHIPS: number = 5;
const ARROW_PADDING: number = 2;

const CHIP_PADDING: number = 3;

export interface IChipSelectorConfig {
    backgroundColor: number;
    borderColor: number;
    backgroundAlpha: number;
    targetScales: { selected: number, unSelected: number };
    showArrows: boolean;
}

export class ChipSelector extends Container {

    private static defaultConfig: IChipSelectorConfig = {
        backgroundColor: 0xffffff,
        borderColor: -1,
        backgroundAlpha: 0.4,
        targetScales: { selected: 1, unSelected: 0.8 },
        showArrows: true
    };

    private _config: IChipSelectorConfig;

    private _currentChipType: number = 0;

    private _leftArrow: Sprite;
    private _rightArrow: Sprite;

    private _background: Graphics;
    private _backgroundPulse: Graphics;
    private _chipHolder: Container;
    private _chipMask: Sprite;

    private _chips: BaseChip[] = [];

    private _wiggleContainer: Container;
    private _wiggleTime: number;

    public get currentChip(): BaseChip {
        return this._chips[this._currentChipType];
    }

    private _chipScroll: Container;

    private _startDragBound:(event: FederatedPointerEvent) => void;
    private _processDragBound:(event: FederatedPointerEvent) => void;
    private _endDragBound:(event: FederatedPointerEvent) => void;
    private _dragOffset: number = 0;
    private _rightLimit: number = 0;

    private _canScroll: boolean = false;

    private _canDrag: boolean = false;
    private _alerting: boolean = false;

    constructor(config: IChipSelectorConfig = ChipSelector.defaultConfig) {
        super();
        this._config = config;
        this._wiggleContainer = new Container();
        this.addChild(this._wiggleContainer);

        this._leftArrow = new Sprite(AssetManager.getTexture('casino-cabinet-arrow'));
        this._leftArrow.scale.set(-0.3, 0.3);
        if (this._config.showArrows) {
            this._wiggleContainer.addChild(this._leftArrow);
        }
        this._leftArrow.position.set(this._leftArrow.width, 0);
        
        this._chipHolder = new Container();
        this._chipMask = new Sprite(Texture.WHITE);
        
        this._chipHolder.addChild(this._chipMask);
        this._chipHolder.mask = this._chipMask;
        if (this._config.showArrows) {
            this._chipHolder.position.set(this._leftArrow.width + ARROW_PADDING + CHIP_PADDING, CHIP_PADDING);
        } else {
            this._chipHolder.position.set(CHIP_PADDING, CHIP_PADDING);
        }

        this._chipScroll = new Container();
        this._chipHolder.addChild(this._chipScroll);

        eventEmitter.on('CASINO_CABINET_DRAG_CHIP_RELEASED', () => {
            const targetChip = this._chips[this._currentChipType];
            targetChip.enterChipSelect(true);
        });

        eventEmitter.on('CASINO_CABINET_DRAG_CHIP_PLACED', () => {
            const targetChip = this._chips[this._currentChipType];
            targetChip.enterChipSelect(false);
        });

        this._startDragBound = this.startDrag.bind(this);
        this._processDragBound = this.processDrag.bind(this);
        this._endDragBound = this.endDrag.bind(this);

        this._chipScroll.interactive = true;
        this._chipScroll.on('pointerdown', this._startDragBound);

        this._background = new Graphics();
        this._wiggleContainer.addChild(this._background);
        
        this._backgroundPulse = new Graphics();
        this._wiggleContainer.addChild(this._backgroundPulse);
        this._backgroundPulse.renderable = false;

        if (this._config.showArrows) {
            this._background.x = this._leftArrow.x + ARROW_PADDING;
            this._backgroundPulse.x = this._background.x;
        }

        this._wiggleContainer.addChild(this._chipHolder);

        this._rightArrow = new Sprite(AssetManager.getTexture('casino-cabinet-arrow'));
        if (this._config.showArrows) {
            this._wiggleContainer.addChild(this._rightArrow);
        }

        this._rightArrow.interactive = true;
        this._rightArrow.on('pointertap', this.scrollRight.bind(this));

        this._leftArrow.interactive = true;
        this._leftArrow.on('pointertap', this.scrollLeft.bind(this));
    }

    public addChips(chips: BaseChip[]) {
        for (let i: number = 0 ; i < chips.length ; i++) {
            const chip = chips[i];
            this._chipScroll.addChild(chip);
            chip.y = chip.height * 0.5;
            chip.setSelected(i === 0, true, this.updatePositions.bind(this), this._config.targetScales);
            chip.enterCabinetMode();
            this._chips.push(chip);

            chip.interactive = true;
            if (chip.selectable) {
                chip.on('pointerdown', () => {
                    this._canDrag = true;
                    this.setSelectedChip(chip);
                });
                chip.on('pointertap', () => {
                    if (chip.selected) {
                        eventEmitter.emit('CASINO_CABINET_CHIP_SELECTED_NO_DRAG', this._currentChipType, chip);
                    }
                });
            } else {
                chip.on('pointerdown', () => {
                    this._canDrag = false;
                });
            }
        }

        this.updatePositions();

        this._canScroll = this._chips.length > VISIBLE_CHIPS;

        this._rightLimit = -this._chips[this._chips.length - VISIBLE_CHIPS].x;

        this._chipMask.width = this._chips[VISIBLE_CHIPS - 1].x + this._chips[VISIBLE_CHIPS - 1].width;
        this._chipMask.height = this._chipHolder.height;

        const targetSize: Point = new Point(this._chipHolder.width + CHIP_PADDING * 2, this._chipHolder.height + CHIP_PADDING * 2);

        this._background.clear();
        this._background.beginFill(this._config.backgroundColor, 1);
        this._background.drawRect(targetSize.y * 0.5, 0, targetSize.x - targetSize.y, targetSize.y);
        this._background.arc(targetSize.y * 0.5, targetSize.y * 0.5, targetSize.y * 0.5, Math.PI * 0.5, Math.PI * 1.5);
        this._background.endFill();
        this._background.beginFill(this._config.backgroundColor, 1);
        this._background.arc(targetSize.x - targetSize.y * 0.5, targetSize.y * 0.5, targetSize.y * 0.5, Math.PI * 0.5, Math.PI * 1.5, true);
        this._background.endFill();
        this._background.alpha = this._config.backgroundAlpha;

        this._backgroundPulse.clear();
        this._backgroundPulse.beginFill(0xff0000, 1);
        this._backgroundPulse.drawRect(targetSize.y * 0.5, 0, targetSize.x - targetSize.y, targetSize.y);
        this._backgroundPulse.arc(targetSize.y * 0.5, targetSize.y * 0.5, targetSize.y * 0.5, Math.PI * 0.5, Math.PI * 1.5);
        this._backgroundPulse.endFill();
        this._backgroundPulse.beginFill(0xff0000, 1);
        this._backgroundPulse.arc(targetSize.x - targetSize.y * 0.5, targetSize.y * 0.5, targetSize.y * 0.5, Math.PI * 0.5, Math.PI * 1.5, true);
        this._backgroundPulse.endFill();
        this._backgroundPulse.alpha = 0.4;

        if (this._config.borderColor !== -1) {
            this._background.lineStyle(2, this._config.borderColor, 1);
            this._background.moveTo(targetSize.y * 0.5, 0);
            this._background.lineTo(targetSize.y * 0.5 + targetSize.x - targetSize.y, 0);

            let center = new Point(targetSize.y * 0.5 + targetSize.x - targetSize.y, targetSize.y * 0.5);
            const radius = targetSize.y * 0.5;
            const segments = 20;

            for (let i = 1; i <= segments; i++) {
                const angle = ((i / segments * 180) - 90) * (Math.PI / 180);
                const x = center.x + Math.cos(angle) * radius;
                const y = center.y + Math.sin(angle) * radius;
                this._background.lineTo(x, y);
            }

            this._background.lineTo(targetSize.y * 0.5, targetSize.y);

            center = new Point(targetSize.y * 0.5, targetSize.y * 0.5);

            for (let i = 1; i <= segments; i++) {
                const angle = ((i / segments * 180) + 90) * (Math.PI / 180);
                const x = center.x + Math.cos(angle) * radius;
                const y = center.y + Math.sin(angle) * radius;
                this._background.lineTo(x, y);
            }
            this._background.closePath();
        }

        this._rightArrow.scale.set(0.3);
        this._rightArrow.position.set(this._leftArrow.x + this._chips[VISIBLE_CHIPS - 1].x + this._chips[VISIBLE_CHIPS - 1].width + (ARROW_PADDING + CHIP_PADDING) * 2, CHIP_PADDING);
    }

    private setSelectedChip(targetChip: BaseChip, instant: boolean = false): void {
        this._chips.forEach((chip: BaseChip, index: number) => {
            if (targetChip === chip) {
                chip.setSelected(true, instant, this.updatePositions.bind(this), this._config.targetScales);
                this._currentChipType = index;
                eventEmitter.emit('CASINO_CABINET_CHIP_SELECTED', this._currentChipType);
            } else {
                chip.setSelected(false, instant, this.updatePositions.bind(this),this._config.targetScales);
            }
        });
    }

    private updatePositions(): void {
        let position: number = 0;
        for (let i = 0 ; i < this._chips.length ; i++) {
            this._chips[i].x = position;
            position += this._chips[i].width;
        }
    }

    private scrollRight(): void {
        const currentSelected = this.currentSelected;
        let nextChip = currentSelected;
        if (currentSelected < this._chips.length - 1) {
            for (let i = nextChip +1; i < this._chips.length ; i++) {
                if (this._chips[i].selectable) {
                    nextChip = i;
                    i = this._chips.length;
                }
            }
            if (nextChip === currentSelected) {
                return;
            }
            this._chips[currentSelected].setSelected(false, false, this.updatePositions.bind(this), this._config.targetScales);
            this._chips[nextChip].setSelected(true, false, this.updatePositions.bind(this), this._config.targetScales);
            eventEmitter.emit('CASINO_CABINET_CHIP_SELECTED', nextChip);
        }

        if (this._canScroll) {
            const currentFocus = this.getCurrentFocus();
            if (nextChip < currentFocus) {
                gsap.killTweensOf(this._chipScroll);
                this.scrollTo(nextChip);
            }
        }
    }

    private get currentSelected(): number {
        for (let i : number = 0 ; i < this._chips.length ; i++) {
            if (this._chips[i].selected) {
                return i;
            }
        }
        return 0;
    }

    private scrollLeft(): void {
        const currentSelected = this.currentSelected;
        let nextChip = currentSelected;
        if (currentSelected > 0) {
            for (let i = nextChip - 1; i >= 0 ; i--) {
                if (this._chips[i].selectable) {
                    nextChip = i;
                    i = -1;
                }
            }
            if (nextChip === currentSelected) {
                return;
            }
            this._chips[currentSelected].setSelected(false, false, this.updatePositions.bind(this), this._config.targetScales);
            this._chips[nextChip].setSelected(true, false, this.updatePositions.bind(this), this._config.targetScales);
            eventEmitter.emit('CASINO_CABINET_CHIP_SELECTED', nextChip);
        }

        if (this._canScroll) {
            const currentFocus = this.getCurrentFocus();
            if (nextChip < currentFocus) {
                gsap.killTweensOf(this._chipScroll);
                this.scrollTo(nextChip);
            }
        }
    }

    private getCurrentFocus(): number {
        const currentX = this._chipScroll.x;
        for (let i: number = 0 ; i < this._chips.length ; i++) {
            const chip = this._chips[i];
            if (chip.x + chip.width * 0.5 > -currentX) {
                return i;
            }
        }
        return 0;
    }

    private scrollTo(target: number): void {
        target = Math.max(0, Math.min(this._chips.length - VISIBLE_CHIPS, target));
        const xPos: number = this._chips[target].x;
        gsap.to(this._chipScroll, { x: -xPos, duration: 0.5 });
    }

    private findStage(): Container {
        return window.$pixi.stage;
    }

    private startDrag(event: FederatedPointerEvent): void {
        this._chipScroll.off('pointerdown', this._startDragBound);
        this.findStage().on('pointermove', this._processDragBound);
        this.findStage().on('pointerup', this._endDragBound);

        const p = this.toLocal(new Point(event.data.global.x, event.data.global.y));
        this._dragOffset = this._chipScroll.x - p.x;
        gsap.killTweensOf(this._chipScroll);
    }

    private processDrag(event: FederatedPointerEvent): void {
        const p = this.toLocal(new Point(event.data.global.x, event.data.global.y));
        if (this._canScroll) {
            this._chipScroll.x = p.x + this._dragOffset;

            if (this._chipScroll.x > 0) {
                this._chipScroll.x = Math.sqrt(this._chipScroll.x);
            } else if (this._chipScroll.x < this._rightLimit) {
                const distance = Math.abs(this._chipScroll.x - this._rightLimit);
                this._chipScroll.x = this._rightLimit - Math.sqrt(distance);
            }
        }

        const top: Point = this.toGlobal(new Point(0, 0));
        if (event.data.global.y < top.y && this._canDrag && this._chips[this.currentSelected].selectable) {
            this.endDrag();
            this._chips[this._currentChipType].startDraggingOffChipHolder();
            eventEmitter.emit('CASINO_CABINET_DRAG_CHIP_STARTED', event.data.global, this._chips[this._currentChipType]);
        }
    }

    private endDrag(): void {
        this.findStage().off('pointerup', this._endDragBound);
        this.findStage().off('pointermove', this._processDragBound);
        this._chipScroll.on('pointerdown', this._startDragBound);

        if (this._canScroll) {
            this.scrollTo(this.getCurrentFocus());
        }
    }

    public resize(width: number, maxHeight: number): void {
        this.width = width;
        this.height = maxHeight;
        this.scale.set(Math.min(this.scale.x, this.scale.y));

        this._leftArrow.position.set(this._leftArrow.x, this._background.height * 0.5 - this._leftArrow.height * 0.5);
        this._rightArrow.position.set(this._rightArrow.x, this._background.height * 0.5 - this._rightArrow.height * 0.5);

    }

    public playInvalidBetAlert(): void {
        if (!this._alerting) {
            this._backgroundPulse.renderable = true;
            this._alerting = true;
            this._wiggleTime = 0;
            gsap.to(this, 
                {
                    duration: 0.5,
                    _wiggleTime: 1,
                    onUpdate: () => {
                        this._wiggleContainer.x = Math.sin(this._wiggleTime * Math.PI * 4) * 10;
                    },
                    onComplete: () => {
                        this._backgroundPulse.renderable = false;
                        this._alerting = false;
                        gsap.killTweensOf(this);
                    }
                });
        }
    }

    public disableInteractivity(): void {
        this.interactiveChildren = false;
        this._chipScroll.interactive = false;
    }

    public enableInteractivity(): void {
        this.interactiveChildren = true;
        this._chipScroll.interactive = true;
    }
}